const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const subject = j.subject || '';
  let body = j.text || '';
  if (!body && j.html) body = String(j.html).replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<[^>]+>/g, ' ');
  if (!body) body = j.snippet || '';
  body = body.replace(/\s+/g, ' ').trim();
  if (!/quiz|assessment|\btest\b|mcq/i.test(subject + ' ' + body)) continue;   // cheap pre-filter, saves AI calls
  const links = (body.match(/https?:\/\/[^\s"'<>)]+/g) || []).slice(0, 10);
  out.push({ json: { subject, links, body: body.slice(0, 6000),
    text: 'Subject: ' + subject + '\nLinks: ' + links.join(' ') + '\n\n' + body.slice(0, 6000) } });
}
return out;

