const out = [];
const all = $input.all();
for (let i = 0; i < all.length; i++) {
  const o = all[i].json.output || {};
  let pre = {};
  try { pre = $('Prepare Text').itemMatching(i).json; } catch (e) {}
  let link = (o.source_link || '').trim();
  if (link && !(pre.links || []).includes(link)) link = '';      // drop hallucinated links
  const v = (x) => x && String(x).trim() ? String(x).trim() : 'not mentioned in email';
  const rows = [['Course', v(o.course)], ['Quiz', v(o.quiz_title)], ['Opens', v(o.start)],
                ['Deadline', v(o.deadline)], ['Duration', v(o.duration)],
                ['Link', link ? `<a href="${link}">Open in vmedulife</a>` : 'not found in email']]
    .map(r => `<tr><td><b>${r[0]}</b></td><td>${r[1]}</td></tr>`).join('');
  out.push({ json: {
    subject: '📝 New quiz assigned: ' + (o.course ? o.course + ' – ' : '') + (o.quiz_title || pre.subject || ''),
    html: `<h2>New quiz assigned</h2><table cellpadding="6">${rows}</table><p>Details are copied from the college email as written. Check the official email or portal to confirm.</p>`
  }});
}
return out;
